<template>
  <div class="hire-workspace" :style="theme">
    <aside class="hire-nav">
      <div class="tenant-brand"><img v-if="agency.logoUrl" :src="agency.logoUrl" :alt="agency.name" /><strong v-else>{{ agency.name }}</strong></div>
      <nav aria-label="Your portal">
        <button :class="{ selected: section === 'home' }" @click="navigate('home')"><Icon name="home" />Home</button>
        <button v-if="onboarding" :class="{ selected: phase === 'pre_hire' && section === 'steps' }" @click="switchPhase('pre_hire')"><Icon />Pre-Hire <span class="nav-check">✓</span></button>
        <button :class="{ selected: section === 'steps' && phase === currentPhase }" @click="switchPhase(currentPhase)"><Icon :name="onboarding ? 'people' : 'document'" />{{ onboarding ? 'Onboarding' : 'Pre-Hire' }}</button>
        <button :class="{ selected: section === 'documents' }" @click="navigate('documents')"><Icon />My Documents</button>
        <button :class="{ selected: section === 'messages' }" @click="navigate('messages')"><Icon name="message" />Messages</button>
        <button :class="{ selected: section === 'help' }" @click="navigate('help')"><Icon name="help" />Help</button>
      </nav>
      <div class="nav-bottom"><svg viewBox="0 0 180 65" aria-hidden="true"><path d="m0 60 42-43 20 13L91 0l40 45 18-16 31 31H0" fill="currentColor" opacity=".18"/><path d="m45 36 17-6L91 0l40 45-34-26-8 9-6-11-21 25Z" fill="currentColor" opacity=".2"/></svg><p>{{ config.tagline || 'Your next chapter starts here.' }}</p></div>
    </aside>
    <div class="hire-page">
      <header class="hire-topbar"><span>{{ agency.name }}</span><div class="person"><img v-if="workflow.headshot" :src="fileUrl('pre_hire', 'headshot')" alt="Your headshot" /><span v-else class="avatar">{{ initials }}</span><strong>{{ name }}</strong></div></header>
      <section class="hire-hero" :style="heroStyle">
        <div><p class="eyebrow">{{ phaseLabel }}</p><h1>{{ pageTitle }}</h1><strong v-if="section === 'steps' && !closed">Step {{ stepIndex + 1 }} of {{ steps.length }}</strong><p>{{ heroDescription }}</p></div>
        <p v-if="config.tagline" class="hero-tagline">{{ config.tagline }}</p>
      </section>
      <div v-if="section === 'messages'" class="messages-page"><slot name="messages" /></div>
      <div v-else-if="section === 'documents'" class="documents-page">
        <div class="card"><h2>Your hire packages</h2><p>Review your submitted information, signed agreements and uploaded files.</p><div class="package-links"><button @click="switchPhase('pre_hire')"><Icon />{{ prehireClosed ? 'View completed pre-hire' : 'View pre-hire progress' }}</button><button v-if="onboarding" @click="switchPhase('onboarding')"><Icon name="people" />View onboarding</button></div></div>
        <slot name="documents" />
      </div>
      <div v-else-if="section === 'help'" class="documents-page"><div class="card"><h2>People Operations is here to help</h2><p>Ask about a document, your account, a meeting, or anything along the way.</p><button class="primary" @click="navigate('messages')"><Icon name="message" />Message People Operations</button></div><div class="card"><h3>Your personal portal link</h3><p>This same private link stays with you through pre-hire and onboarding.</p><div class="copy-line"><input :value="portalLink" readonly aria-label="Your personal portal link" /><button @click="copyLink"><Icon name="copy" />{{ copied ? 'Copied' : 'Copy' }}</button></div></div></div>
      <div v-else class="hire-body" :class="{ overview: section === 'home' }">
        <aside v-if="section === 'steps'" class="step-sidebar card">
          <h2>{{ phaseLabel }} progress</h2><progress :value="progress.percent" max="100" :aria-label="`${phaseLabel} completion`" /><div class="progress-caption"><span>{{ progress.completed }} of {{ progress.total }} required items</span><strong>{{ progress.percent }}%</strong></div>
          <ol class="steps"><li v-for="(item, i) in steps" :key="item.key"><button :class="{ current: item.key === selectedKey, complete: item.complete }" :aria-current="item.key === selectedKey ? 'step' : undefined" @click="select(item)"><span class="step-dot"><Icon v-if="item.complete" name="check" /><span v-else>{{ i + 1 }}</span></span><span>{{ item.title }}<small v-if="item.required === false && item.kind !== 'review'">Optional</small></span></button></li></ol>
          <button v-if="onboarding && phase === 'onboarding'" class="archive-link" @click="switchPhase('pre_hire')"><Icon name="back" /><span><strong>Back to Pre-Hire</strong><small>View your completed information and documents.</small></span></button>
          <button v-else-if="onboarding" class="archive-link" @click="switchPhase('onboarding')"><Icon name="arrow" />Return to onboarding</button>
        </aside>
        <main class="hire-main" aria-live="polite">
          <div v-if="closed" class="notice review-notice"><Icon name="clock" /><div><strong>{{ phase === 'pre_hire' ? 'Pre-hire complete' : 'Onboarding submitted' }} · {{ phase === 'pre_hire' && onboarding ? 'Retained package' : 'Waiting for review' }}</strong><p>{{ phase === 'pre_hire' ? 'Your submitted information remains available below. People Operations will start onboarding when your review is complete.' : 'Your package is ready for People Operations. Your recorded onboarding time has been submitted for payroll review. Staff will activate your account after review.' }}</p></div></div>
          <template v-if="section === 'home'">
            <div class="card overview-progress"><div><h2>Your {{ phaseLabel.toLowerCase() }} progress</h2><p>{{ progress.completed }} of {{ progress.total }} required items complete</p><progress :value="progress.percent" max="100" /></div><strong>{{ progress.percent }}%</strong><button class="primary" @click="navigate('steps')">{{ closed ? 'View your package' : 'Continue your steps' }}<Icon name="arrow" /></button></div>
            <div class="overview-grid"><div class="card"><div class="card-heading"><Icon name="people" /><h2>{{ name }}</h2></div><img v-if="workflow.headshot" class="profile-photo" :src="fileUrl('pre_hire', 'headshot')" alt="Your professional headshot" /><p>{{ candidate.appliedRole || 'Your employment journey' }}</p><dl><dt>{{ candidate.workEmail ? 'Work username' : 'Preferred work email' }}</dt><dd>{{ candidate.workEmail || workflow.preferredWorkEmail || 'Choose during pre-hire' }}</dd><template v-if="onboarding"><dt>Supervisor</dt><dd>{{ workflow.supervisor?.name || 'People Operations will confirm your supervisor' }}</dd></template></dl></div><div class="card"><div class="card-heading"><Icon name="link" /><h2>Your personal portal link</h2></div><p>Use this same link for pre-hire and onboarding. Keep it private.</p><div class="copy-line"><input :value="portalLink" readonly aria-label="Your personal portal link" /><button @click="copyLink"><Icon name="copy" />{{ copied ? 'Copied' : 'Copy' }}</button></div></div></div>
            <div class="card"><h2>Your step-by-step checklist</h2><div v-for="item in steps.filter(s => s.kind !== 'review')" :key="item.key" class="checklist-row"><span class="check-circle" :class="{ done: item.complete }"><Icon :name="item.complete ? 'check' : iconFor(item)" /></span><div><strong>{{ item.title }}</strong><small>{{ item.complete ? 'Completed and saved' : item.required === false ? 'Optional' : 'Required' }}</small></div><span class="badge" :class="{ done: item.complete }">{{ item.complete ? 'Complete' : 'To do' }}</span><button :aria-label="`View ${item.title}`" @click="select(item); navigate('steps')">View</button></div></div>
          </template>
          <template v-else-if="step">
            <div class="card current-heading"><span class="large-icon"><Icon :name="iconFor(step)" /></span><div><h2>{{ step.title }}</h2><p>{{ step.instructions || (closed ? 'Your retained submission' : step.complete ? 'Completed and saved to your hire record.' : 'Complete this item, then continue to your next step.') }}</p></div><span v-if="step.complete" class="badge done">Completed</span></div>
            <p v-if="error" class="notice error" role="alert">{{ error }}</p><p v-if="savedMessage" class="notice success" role="status">{{ savedMessage }}</p>
            <div v-if="step.kind === 'profile'" class="card">
              <p>This information is collected for individuals under consideration with {{ agency.name }}. People Operations will review your submission. Submitting does not guarantee employment or finalize an offer.</p>
              <form @submit.prevent="saveProfile(true)"><fieldset :disabled="closed || busy"><div class="profile-grid"><label v-for="field in workflow.profileFields" :key="field.key" :class="{ wide: field.type === 'textarea' }">{{ field.label }}<span v-if="field.required"> *</span><textarea v-if="field.type === 'textarea'" v-model="profile[field.key]" rows="3" /><input v-else v-model="profile[field.key]" :type="field.type === 'phone' ? 'tel' : field.type" :required="field.required" /></label></div></fieldset><div v-if="!closed" class="form-actions"><button type="button" :disabled="busy" @click="saveProfile(false)">Save for later</button><button class="primary" :disabled="busy">{{ busy ? 'Saving…' : 'Save information' }}</button></div></form>
              <div class="upload-card"><h3>Resume, CV or work history</h3><p>Optional · One PDF, Word document or image, up to 10 MB.</p><a v-if="workflow.resume" :href="fileUrl('pre_hire','resume')" target="_blank" rel="noopener">{{ workflow.resume.name || 'View uploaded resume' }}</a><input v-if="!closed" type="file" accept=".pdf,.doc,.docx,.jpg,.jpeg,.png,.webp" aria-label="Upload resume" :disabled="busy" @change="upload('resume', $event)" /></div>
            </div>
            <div v-else-if="step.kind === 'headshot'" class="card"><h3>A face to go with your name</h3><p>Add a professional headshot for your profile and your organization’s team materials. Choose one JPEG, PNG or WebP image, up to 10 MB.</p><img v-if="workflow.headshot" class="headshot-preview" :src="fileUrl('pre_hire','headshot')" alt="Your professional headshot" /><label v-if="!closed" class="upload-card"><Icon name="camera" /><span>{{ workflow.headshot ? 'Replace your headshot' : 'Upload your professional headshot' }}</span><input type="file" accept="image/jpeg,image/png,image/webp" :disabled="busy" @change="upload('headshot', $event)" /></label></div>
            <div v-else-if="step.kind === 'work-email' && data.hireAccountMode !== 'group_password'" class="card"><h3>Your preferred work email</h3><p>People Operations will confirm availability and provision your account.</p><form @submit.prevent="save('work-email', { email: preferredEmail })"><label>Preferred address<input v-model="preferredEmail" type="email" required :disabled="closed" /></label><button v-if="!closed" class="primary" :disabled="busy">Save preference</button></form></div>
            <div v-else-if="['handbook','link','video','meeting','acknowledgement','upload'].includes(step.kind)" class="card resource-step">
              <template v-if="step.url">
                <template v-if="step.kind === 'meeting'"><div class="meeting-person"><Icon name="people" /><div><strong>{{ step.title }}</strong><p>{{ workflow.supervisor?.name }}</p></div></div><a class="primary button" :href="step.url" target="_blank" rel="noopener">Open meeting scheduler<Icon name="calendar" /></a><p>After booking, enter the date and time from your confirmation.</p><label>Confirmed meeting time<input v-model="scheduledAt" type="datetime-local" :disabled="closed || step.complete" /></label></template>
                <template v-else-if="step.kind === 'upload'"><a class="primary button" :href="step.url" target="_blank" rel="noopener">Download blank form<Icon name="document" /></a><p>Complete the form, then upload your completed copy.</p><a v-if="step.complete" :href="fileUrl(phase, step.key)" target="_blank" rel="noopener">View submitted file</a><input v-if="!closed && !step.complete" type="file" accept=".pdf,.doc,.docx,.png,.jpg,.jpeg,.webp" :disabled="busy" @change="upload(step.key, $event)" /></template>
                <video v-else-if="step.kind === 'video' && /\.(mp4|webm)(\?|$)/i.test(step.url)" controls preload="metadata" :src="step.url" @play="$emit('media', true)" @pause="$emit('media', false)" @ended="$emit('media', false)" />
                <iframe v-else-if="embedUrl(step.url)" class="resource-frame" :src="embedUrl(step.url)" :title="step.title" allow="fullscreen" referrerpolicy="no-referrer" @load="registerMediaFrame" />
                <a v-else class="button" :href="step.url" target="_blank" rel="noopener">Open {{ step.title }}<Icon name="arrow" /></a>
                <p v-if="step.kind === 'handbook'" class="muted"><a :href="step.url" target="_blank" rel="noopener">Open handbook in a new tab ↗</a>. If the viewer requests access, contact People Operations.</p>
                <template v-if="step.kind !== 'upload' && !closed && !step.complete"><label class="check-label"><input v-model="acknowledged" type="checkbox" />{{ step.kind === 'meeting' ? 'I have booked this meeting.' : step.kind === 'video' ? 'I have watched this video.' : 'I have reviewed this information.' }}</label><AdaptiveSignatureCapture v-if="needsSignature" v-model="signature" title="Your acknowledgement" :signer-name="name" /><button class="primary" :disabled="busy || !acknowledged || (needsSignature && !signature)" @click="save(step.key, { acknowledged, signatureData: signature, scheduledAt })">{{ busy ? 'Saving…' : needsSignature ? 'Sign acknowledgement' : 'Save completion' }}</button></template>
                <p v-if="step.submission?.scheduledAt">Scheduled for {{ new Date(step.submission.scheduledAt).toLocaleString() }}</p><a v-if="step.submission?.receiptPath" :href="fileUrl(phase,step.key)" target="_blank" rel="noopener">View signed acknowledgement</a>
              </template><div v-else class="notice"><Icon name="clock" /><p>People Operations needs to attach this resource. Message the team so they can help you continue.</p></div>
            </div>
            <div v-else-if="step.kind === 'clinical-profile'" class="card"><HireClinicalProfile :step="step" :busy="busy" :readonly="closed" @save="save(step.key, $event)" /></div>
            <div v-else-if="step.kind === 'task' && step.task.taskType === 'training'" class="card embedded-training"><iframe :key="step.key" :src="`/pre-hire/${token}/module/${step.task.referenceId}?embedded=1`" :title="step.title" /></div>
            <div v-else-if="step.kind === 'task' && step.task.taskType === 'intake_form'" class="card"><iframe v-if="intakeUrl(step.task)" class="resource-frame" :src="intakeUrl(step.task)" :title="step.title" /><button v-if="!closed && !step.complete" class="primary" @click="$emit('complete-task', step.task)">Check form submission</button></div>
            <div v-else-if="step.kind === 'task'" class="card"><p>{{ step.task.description }}</p><button class="primary" :disabled="closed && !step.complete" @click="step.task.taskType === 'custom' ? $emit('complete-task', step.task) : $emit('document', step.task)"><Icon />{{ step.complete ? 'View saved document' : step.task.taskType === 'custom' ? 'Mark complete' : 'Open, review and sign' }}</button></div>
            <div v-else-if="step.kind === 'review'" class="card"><h2>{{ closed ? 'Your completed package' : 'Review your checklist' }}</h2><p>{{ closed ? 'Your submissions are retained in My Documents and your employee library.' : 'Make sure the information you provided is complete and accurate before submitting to People Operations.' }}</p><div v-for="item in steps.filter(s => s.kind !== 'review')" :key="item.key" class="checklist-row"><Icon :name="item.complete ? 'check' : 'clock'" /><strong>{{ item.title }}</strong><span class="badge" :class="{ done: item.complete }">{{ item.complete ? 'Complete' : item.required === false ? 'Optional' : 'To do' }}</span><button @click="select(item)">View</button></div><template v-if="!closed"><label class="check-label"><input v-model="certified" type="checkbox" />I confirm that my information is complete and accurate.</label><button class="primary" :disabled="!certified || !progress.allDone" @click="$emit('submit')">Submit {{ phaseLabel.toLowerCase() }} for review<Icon name="arrow" /></button></template></div>
            <div v-else-if="step.kind === 'unavailable'" class="card"><p>{{ step.instructions }}</p><button @click="navigate('messages')">Message People Operations</button></div>
            <slot v-else :name="step.kind" :step="step" :closed="closed" />
            <div class="step-actions"><button :disabled="stepIndex === 0" @click="select(steps[stepIndex-1])"><Icon name="back" />Back</button><span>{{ stepIndex + 1 }} / {{ steps.length }}</span><button v-if="stepIndex < steps.length - 1" class="primary" @click="select(steps[stepIndex+1])">{{ step.complete || closed ? 'Continue' : 'Next step' }}<Icon name="arrow" /></button></div>
          </template>
        </main>
        <aside class="support-rail">
          <div class="card status-card"><h2>{{ phaseLabel }} status</h2><div class="status-title"><Icon :name="closed ? 'clock' : 'people'" /><strong>{{ closed ? (phase === 'pre_hire' && onboarding ? 'Completed' : 'Waiting for review') : 'In progress' }}</strong></div><p>{{ closed ? 'Your information is saved. You can return here to review it at any time.' : 'Follow your steps at your own pace. Your saved progress stays with you.' }}</p><dl v-if="onboarding"><dt>Supervisor</dt><dd>{{ workflow.supervisor?.name || 'To be confirmed' }}</dd><dt>Your login</dt><dd>{{ candidate.workEmail || 'To be confirmed' }}</dd></dl></div>
          <div v-if="phase === 'onboarding'" class="card"><div class="card-heading"><Icon name="clock" /><h2>Your onboarding time</h2></div><slot name="time" /></div>
          <div class="card"><div class="card-heading"><Icon name="help" /><h2>Need help?</h2></div><p>Your People Operations team is here to support you through every step.</p><button class="primary" @click="navigate('messages')"><Icon name="mail" />Contact People Operations</button></div>
          <div class="welcome-card" :style="heroStyle"><p>{{ config.tagline || 'A new beginning. A place to make a difference.' }}</p><img v-if="agency.logoUrl" :src="agency.logoUrl" :alt="agency.name" /><strong v-else>{{ agency.name }}</strong></div>
        </aside>
      </div>
      <footer>© {{ new Date().getFullYear() }} {{ agency.name }}.<button @click="navigate('help')">Contact &amp; help</button></footer>
    </div>
  </div>
</template>

<script setup>
import { computed, ref, watch, onMounted, onBeforeUnmount, nextTick } from 'vue';
import Icon from './HirePortalIcon.vue';
import HireClinicalProfile from './HireClinicalProfile.vue';
import AdaptiveSignatureCapture from '../adaptive-intake/AdaptiveSignatureCapture.vue';
import { buildFormUrl } from '../../utils/publicIntakeUrl.js';
const props = defineProps({ data: { type: Object, required: true }, token: { type: String, required: true }, http: { type: Object, required: true } });
const emit = defineEmits(['phase', 'section', 'reload', 'document', 'complete-task', 'submit', 'media']);
const candidate = computed(() => props.data.candidate || {});
const agency = computed(() => props.data.agency || {});
const workflow = computed(() => props.data.workflow || {});
const config = computed(() => workflow.value.config || {});
const onboarding = computed(() => candidate.value.status === 'ONBOARDING');
const currentPhase = computed(() => onboarding.value ? 'onboarding' : 'pre_hire');
const phase = ref(currentPhase.value);
const section = ref('home');
const selectedKey = ref('');
const prehireClosed = computed(() => !!props.data.journey?.prehireCompletedAt || ['PREHIRE_REVIEW','ONBOARDING'].includes(candidate.value.status));
const closed = computed(() => phase.value === 'pre_hire' ? prehireClosed.value : !!props.data.journey?.onboardingCompletedAt);
const steps = computed(() => workflow.value.steps?.[phase.value] || []);
const progress = computed(() => workflow.value.progress?.[phase.value] || { total: 0, completed: 0, percent: 0 });
const stepIndex = computed(() => Math.max(0, steps.value.findIndex(s => s.key === selectedKey.value)));
const step = computed(() => steps.value[stepIndex.value]);
const phaseLabel = computed(() => phase.value === 'pre_hire' ? 'Pre-Hire' : 'Onboarding');
const name = computed(() => `${candidate.value.firstName || ''} ${candidate.value.lastName || ''}`.trim());
const initials = computed(() => `${candidate.value.firstName?.[0] || ''}${candidate.value.lastName?.[0] || ''}`);
const pageTitle = computed(() => section.value === 'steps' ? step.value?.title || phaseLabel.value : ({ documents: 'My Documents', messages: 'Messages', help: 'How can we help?' }[section.value] || (closed.value ? `${phaseLabel.value} complete` : `Welcome, ${candidate.value.firstName}!`)));
const heroDescription = computed(() => section.value === 'home' ? `Your next steps with ${agency.value.name}. Everything you need, one step at a time.` : section.value === 'steps' ? `Your ${phaseLabel.value.toLowerCase()} information and progress, all in one place.` : 'Stay connected. Get answers. Move forward together.');
const brandColor = computed(() => /^#[0-9a-f]{3,8}$/i.test(agency.value.primaryColor || '') ? agency.value.primaryColor : '#064c40');
const theme = computed(() => ({ '--hire-brand': brandColor.value }));
const heroStyle = computed(() => ({ backgroundImage: `linear-gradient(90deg, color-mix(in srgb, ${brandColor.value} 90%, transparent), #102c3f55), url("${(config.value.bannerUrl || '/assets/kimi/mountains.png').replace(/["\\\n\r]/g, '')}")` }));
const portalLink = computed(() => props.data.portalLink || `${window.location.origin}/pre-hire/${props.token}`);
const copied = ref(false), busy = ref(false), error = ref(''), savedMessage = ref(''), acknowledged = ref(false), signature = ref(''), scheduledAt = ref(''), certified = ref(false);
const profile = ref({ ...workflow.value.profile });
const preferredEmail = ref(workflow.value.preferredWorkEmail || '');
const needsSignature = computed(() => step.value?.kind === 'acknowledgement' || (step.value?.kind === 'handbook' && phase.value === 'onboarding'));
watch(currentPhase, (value) => { phase.value = value; selectedKey.value = ''; });
watch(() => workflow.value.profile, (value, previous) => { if (!busy.value && JSON.stringify(profile.value) === JSON.stringify(previous || {})) profile.value = { ...value }; });
watch(() => step.value?.key, () => { emit('media', false); error.value = ''; savedMessage.value = ''; acknowledged.value = false; signature.value = ''; scheduledAt.value = ''; emit('section', section.value, step.value); });
function navigate(value) { emit('media', false); section.value = value; emit('section', value, step.value); }
function select(item) { if (!item) return; selectedKey.value = item.key; nextTick(() => { const current = document.querySelector('.steps [aria-current=step]'); if (window.innerWidth < 761) current?.scrollIntoView({ block: 'nearest', inline: 'center' }); }); }
function switchPhase(value) { phase.value = value; selectedKey.value = steps.value.find(s => !s.complete)?.key || steps.value[0]?.key || ''; emit('phase', value); navigate('steps'); }
function iconFor(item) { return ({ background: 'lock', 'job-description': 'document', 'work-email': 'mail', profile: 'people', 'clinical-profile': 'people', headshot: 'camera', handbook: 'book', account: 'lock', meeting: 'calendar', video: 'video', upload: 'upload', link: 'link', review: 'check' })[item.kind] || (item.task?.taskType === 'training' ? 'video' : 'document'); }
function fileUrl(p, key) { return `${props.http.defaults.baseURL}/prehire-portal/${encodeURIComponent(props.token)}/workflow/${p}/${encodeURIComponent(key)}/file${key === 'headshot' ? `?v=${encodeURIComponent(workflow.value.headshot?.version || '')}` : ''}`; }
function intakeUrl(task) { const t = task.metadata?.intakeLinkPublicKey || task.metadata?.intakeToken || task.metadata?.intakeLinkToken; return t ? buildFormUrl(t, task.metadata?.formType || task.metadata?.form_type) : task.metadata?.formUrl || ''; }
function embedUrl(raw) {
  try { const u = new URL(raw); if (u.protocol !== 'https:') return '';
    if (u.hostname === 'drive.google.com') { const id = u.pathname.match(/\/d\/([^/]+)/)?.[1] || u.searchParams.get('id'); return id ? `https://drive.google.com/file/d/${encodeURIComponent(id)}/preview` : ''; }
    if (u.hostname === 'docs.google.com') return raw.replace(/\/edit.*$/, '/preview');
    if (['www.youtube.com','youtube.com','youtu.be'].includes(u.hostname)) { const id = u.hostname === 'youtu.be' ? u.pathname.slice(1) : u.searchParams.get('v') || u.pathname.split('/embed/')[1]; return /^[\w-]{11}$/.test(id || '') ? `https://www.youtube-nocookie.com/embed/${id}?enablejsapi=1&origin=${encodeURIComponent(window.location.origin)}` : ''; }
    if (['vimeo.com','www.vimeo.com','player.vimeo.com'].includes(u.hostname)) { const id = u.pathname.match(/\d+/)?.[0]; return id ? `https://player.vimeo.com/video/${id}?api=1&dnt=1` : ''; }
    return /\.pdf($|\?)/i.test(raw) ? raw : '';
  } catch { return ''; }
}
async function copyLink() { try { await navigator.clipboard.writeText(portalLink.value); copied.value = true; } catch { error.value = 'Select and copy your personal link from the field.'; } }
async function save(key, body) { busy.value = true; error.value = ''; savedMessage.value = ''; try { await props.http.post(`/prehire-portal/${props.token}/workflow/${key}`, body); savedMessage.value = body.complete === false ? 'Draft saved. Complete this step when you are ready.' : 'Saved to your hire record.'; emit('reload'); } catch (e) { error.value = e.response?.data?.error?.message || 'Unable to save. Please try again.'; } finally { busy.value = false; } }
const saveProfile = (complete) => save('profile', { values: profile.value, complete });
async function upload(key, event) { const file = event.target.files?.[0]; if (!file) return; if (file.size > 10 * 1024 * 1024) { error.value = 'Choose a file up to 10 MB.'; return; } busy.value = true; error.value = ''; try { const body = new FormData(); body.append('file', file); await props.http.post(`/prehire-portal/${props.token}/workflow/${key}/upload`, body); savedMessage.value = 'Your file has been saved.'; emit('reload'); } catch (e) { error.value = e.response?.data?.error?.message || 'Upload failed. Please try again.'; } finally { busy.value = false; event.target.value = ''; } }
function registerMediaFrame(event) {
  if (step.value?.kind !== 'video') return;
  const frame = event.target;
  const origin = new URL(frame.src).origin;
  if (origin === 'https://www.youtube-nocookie.com') {
    frame.contentWindow.postMessage(JSON.stringify({ event: 'listening', id: 'hire-video' }), origin);
    frame.contentWindow.postMessage(JSON.stringify({ event: 'command', func: 'addEventListener', args: ['onStateChange'] }), origin);
  } else if (origin === 'https://player.vimeo.com') {
